package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.expression.Expression;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class CoreOperationNotEqual_CoreOperationNotEqual_TriageGen0Test {

    @Test
    public void testConstructorAndGetSymbol() {
        // Arrange
        Expression arg1 = Mockito.mock(Expression.class);
        Expression arg2 = Mockito.mock(Expression.class);

        // Act
        CoreOperationNotEqual operation = new CoreOperationNotEqual(arg1, arg2);

        // Assert
        assertNotNull(operation);
        // Based on JXPath implementation, the symbol for NotEqual is usually "!=" or similar
        // We verify it returns a non-null string as per the method signature
        assertNotNull(operation.getSymbol());
    }

    @Test
    public void testComputeValue() {
        // Arrange
        Expression arg1 = Mockito.mock(Expression.class);
        Expression arg2 = Mockito.mock(Expression.class);
        EvalContext context = Mockito.mock(EvalContext.class);

        // Mock the behavior of the underlying expressions
        // Since CoreOperationNotEqual extends a base class that likely calls arg1.computeValue(context)
        // and arg2.computeValue(context), we simulate the values.
        Mockito.when(arg1.computeValue(context)).thenReturn("A");
        Mockito.when(arg2.computeValue(context)).thenReturn("B");

        CoreOperationNotEqual operation = new CoreOperationNotEqual(arg1, arg2);

        // Act
        Object result = operation.computeValue(context);

        // Assert
        // "A" != "B" should return true
        assertEquals(true, result);
    }

    @Test
    public void testComputeValueEquality() {
        // Arrange
        Expression arg1 = Mockito.mock(Expression.class);
        Expression arg2 = Mockito.mock(Expression.class);
        EvalContext context = Mockito.mock(EvalContext.class);

        Mockito.when(arg1.computeValue(context)).thenReturn("A");
        Mockito.when(arg2.computeValue(context)).thenReturn("A");

        CoreOperationNotEqual operation = new CoreOperationNotEqual(arg1, arg2);

        // Act
        Object result = operation.computeValue(context);

        // Assert
        // "A" != "A" should return false
        assertEquals(false, result);
    }

    @Test
    public void testComputeValueNulls() {
        // Arrange
        Expression arg1 = Mockito.mock(Expression.class);
        Expression arg2 = Mockito.mock(Expression.class);
        EvalContext context = Mockito.mock(EvalContext.class);

        Mockito.when(arg1.computeValue(context)).thenReturn(null);
        Mockito.when(arg2.computeValue(context)).thenReturn("A");

        CoreOperationNotEqual operation = new CoreOperationNotEqual(arg1, arg2);

        // Act
        Object result = operation.computeValue(context);

        // Assert
        // null != "A" is true
        assertEquals(true, result);
    }
}
